<script setup lang="ts">
import {ref,computed} from 'vue';
import type {Console,Row} from '../console';
import Icon from './Icon.vue';
const props=defineProps<{c:Console}>();
const files=ref<Record<string,File|null>>({employees:null,departments:null,permissions:null});
const preview=ref<Row|null>(null),result=ref<Row|null>(null);
const slots=[{key:'employees',label:'员工信息表',detail:'姓名、用户名、分公司、部门、岗位、电话',number:'01'}, {key:'departments',label:'部门信息表',detail:'部门名称、部门经理、上级部门',number:'02'}, {key:'permissions',label:'功能权限清单',detail:'应用、模块、功能与五类角色的操作矩阵',number:'03'}];
const ready=computed(()=>Object.values(files.value).every(Boolean));
/** 文件变化后摘要失效，禁止把旧预览用于新文件。 */
function choose(key:string,event:Event){files.value[key]=(event.target as HTMLInputElement).files?.[0]||null;preview.value=null;result.value=null;}
function form(){const data=new FormData();for(const [key,file] of Object.entries(files.value))if(file)data.append(key,file);return data;}
async function inspect(){await props.c.run(async()=>{preview.value=null;result.value=null;preview.value=await props.c.api('/api/imports/company/preview','POST',form());});}
async function commit(){if(!preview.value)return;await props.c.run(async()=>{const data=form();data.append('digest',preview.value!.digest);result.value=await props.c.api('/api/imports/company/commit','POST',data);preview.value=null;await props.c.refresh();props.c.message('三张表已导入，来源字段已保留');});}
</script>
<template><div class="import-workspace"><section class="panel import-intro"><div><p class="eyebrow">DATA INTAKE / 三表联动</p><h2>从原始清单，到有序的权限目录。</h2><p class="muted">先检查数据，再确认写入。部门简称按所属分公司匹配，同一批数据重复导入会复用已有记录。</p></div><span class="import-emblem"><Icon name="organization" :size="36"/></span></section><div class="import-steps"><span class="active"><b>1</b>选择三张表</span><i/><span :class="{active:preview||result}"><b>2</b>预览与校验</span><i/><span :class="{active:result}"><b>3</b>确认与完成</span></div><section class="panel"><div class="section-heading"><div><h2>选择来源文件</h2><p class="muted">仅支持指定模板的 .xlsx 文件，每张不超过 8 MB。</p></div><span class="badge neutral">三表一起校验</span></div><div class="import-files"><label v-for="slot in slots" :key="slot.key" class="file-slot" :class="{chosen:files[slot.key]}"><span class="file-number">{{slot.number}}</span><strong>{{slot.label}}</strong><small>{{slot.detail}}</small><input type="file" accept=".xlsx" :aria-label="slot.label" :disabled="c.s.busy" @change="choose(slot.key,$event)"><span class="file-name">{{files[slot.key]?.name||'选择 Excel 文件'}}</span></label></div><div class="import-toolbar"><span class="muted">文件只用于本次请求，页面不展示员工明细。</span><button class="primary" :disabled="!ready||c.s.busy" @click="inspect"><Icon name="search"/>{{c.s.busy?'处理中…':'预览并校验'}}</button></div></section><section class="panel import-review" :class="{complete:result}"><div class="section-heading"><div><p class="eyebrow">{{result?'IMPORT COMPLETED':'REVIEW BEFORE COMMIT'}}</p><h2>{{result?'导入已完成':preview?'校验通过，可以导入':'等待文件校验'}}</h2><p class="muted">{{result?'数据已保存，可以继续设置账号和授权关系。':preview?'请确认以下汇总与处理规则，再写入系统。':'选择三张来源表并点击「预览并校验」。校验通过前不会写入。'}}</p></div><Icon :name="result?'check':'shield'" :size="28"/></div><template v-if="preview||result"><div class="import-counts"><div v-for="[key,label] in [['employees','员工'],['departments','部门'],['systems','应用'],['modules','模块'],['functions','功能点'],['roleTemplates','角色模板']]" :key="key"><strong>{{(result||preview)?.[key].toLocaleString()}}</strong><span>{{label}}</span></div></div><p class="import-match">已按分公司补全 <strong>{{(result||preview)?.qualifiedDepartments.toLocaleString()}}</strong> 条员工部门简称。</p><ul class="import-notes"><li v-for="note in (result||preview)?.notes" :key="note"><Icon name="info" :size="16"/>{{note}}</li></ul><details class="import-digest"><summary>文件校验摘要</summary><code>{{(result||preview)?.digest}}</code></details></template><div class="import-toolbar"><span class="muted">导入模板的操作授权以清单为准；现有账号的密码、状态与个人授权保留。</span><button v-if="result" class="primary" @click="c.select('users')">查看员工<Icon name="arrow"/></button><button v-else class="primary" :disabled="!preview||c.s.busy" @click="commit">确认导入<Icon name="check"/></button></div></section></div></template>
